  })).filter(b => b.text.toLowerCase().includes('filter') || b.text.toLowerCase().includes('house') || b.text.toLowerCase().includes('price') || b.testId);

  // Also check if there's any filter drawer / sidebar in DOM
  const drawers = Array.from(document.querySelectorAll('[class*="filter"], [class*="Filter"], [id*="filter"]')).map(el => ({
    tagName: el.tagName,
    className: el.className,
    id: el.id,
    display: window.getComputedStyle(el).display,
    visibility: window.getComputedStyle(el).visibility
  }));

  return { allButtons, drawersCount: drawers.length, drawers: drawers.slice(0, 10) };
});
