const res = await browserjs(tabId, () => {
  // Let's inspect window errors or find the component instance
  const btn = document.querySelector('[data-testid="lw-laf-filters-button"]');
  const fiberKey = Object.keys(btn).find(k => k.startsWith('__reactFiber$'));
  const fiber = btn[fiberKey];

  // Let's traverse up the fiber tree to see state / handlers
  let curr = fiber;
  const path = [];
  while (curr) {
    if (curr.memoizedProps && Object.keys(curr.memoizedProps).length > 0) {
      path.push({
        type: typeof curr.type === 'string' ? curr.type : (curr.type?.name || curr.type?.displayName || 'Component'),
        props: Object.keys(curr.memoizedProps),
        state: curr.memoizedState ? Object.keys(curr.memoizedState) : null
      });
    }
    curr = curr.return;
  }
  return path.slice(0, 10);
});
console.log(JSON.stringify(res, null, 2));

