    const heading = sec.querySelector("h3")?.textContent.trim();
    const inputs = Array.from(sec.querySelectorAll("input, select, a, button")).map(el => ({
      tagName: el.tagName,
      type: el.type,
      name: el.name,
      id: el.id,
      text: el.textContent.trim(),
      placeholder: el.placeholder,
      value: el.value,
      href: el.getAttribute("href"),
      checked: el.checked
    }));
    return { heading, inputCount: inputs.length, inputs: inputs.slice(0, 15) };
  });

  const footer = modal.querySelector('[data-testid="modal-footer-container"]') || modal.querySelector('.land-ui-modal-footer');
  const footerButtons = footer ? Array.from(footer.querySelectorAll('button')).map(b => b.textContent.trim()) : [];

  return { sections, footerButtons };
});

